import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 65 话 主题与明暗体系的构建","description":"","frontmatter":{},"headers":[],"relativePath":"comics/architecture/EP.65-theming-dark-light.md","filePath":"comics/architecture/EP.65-theming-dark-light.md","lastUpdated":1793853676000}'),i={name:"comics/architecture/EP.65-theming-dark-light.md"};function d(l,e,c,h,n,s){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-65-话-主题与明暗体系的构建" tabindex="-1">漫画 · 第 65 话 主题与明暗体系的构建 <a class="header-anchor" href="#漫画-·-第-65-话-主题与明暗体系的构建" aria-label="Permalink to &quot;漫画 · 第 65 话 主题与明暗体系的构建&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/architecture/03-theming-dark-light">docs/architecture/03-theming-dark-light.md</a> ｜ 原画：<a href="./EP.65-theming-dark-light.svg">EP.65-theming-dark-light.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她给内容后台补暗色主题，结果用户反馈「先白闪一下」「弹窗还是白底」。</li><li><strong>码叔</strong>：经验丰富的老工程师。他提醒：主题不是颜色集合，而是系统偏好、应用主题、组件适配三层契约。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>暗色主题上线后问题集中在三处：主题脚本在 body 末尾执行，首帧先浅色；部分组件写死 <code>#fff</code>；Portal 浮层挂到 body 后没有继承主题。码叔把主题引导脚本移到 head 内联执行，组件改为消费语义令牌，浮层显式复制主题属性，并给关键文本加了对比度自检。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>首屏闪白不是「样式加载慢」，而是主题决策发生得太晚。只要 <code>data-theme</code> 在首帧之后才写入，浏览器就一定先用默认浅色画一帧。弹窗则是另一个边界问题：Portal 脱离了页面节点，主题作用域没有跟过去。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三个层次要分开：系统偏好由 <code>prefers-color-scheme</code> 与 <code>color-scheme</code> 表达；应用主题由 <code>[data-theme]</code> 加语义令牌映射；组件只消费语义令牌，不判断明暗。<code>light-dark()</code> 可按 <code>color-scheme</code> 取值，减少重复变量，但要求主题严格二分。切换时保存的是用户模式（light/dark/system），不是解析后的明暗值。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>防闪的关键顺序是：head 内联脚本读 <code>localStorage</code> 与系统偏好 → 立刻写 <code>document.documentElement.dataset.theme</code> → CSS 在 <code>:root[data-theme=&quot;dark&quot;]</code> 下重绑语义令牌。Portal 容器显式复制主题属性。示例里实时显示前景与背景的对比度，暗色选中行从不足 2:1 修到 ≥4.5:1。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>系统偏好只是默认输入，应用主题负责重绑语义层，组件只消费令牌。</li><li>保存 <code>system</code> 模式，系统切换时才能继续跟随。</li><li>首屏脚本必须内联在 <code>&lt;head&gt;</code>，任何外部脚本或后置执行都会闪。</li><li><code>color-scheme: light dark</code> 管的是系统 UI（滚动条、表单控件），不会自动改自定义颜色。</li><li>对比度要脚本校验：正文 4.5:1、大字 3:1，不能凭「看起来还行」。</li><li>暗色不是简单反相，需重调色相、饱和度与阴影。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么主题切换要保存 <code>system</code>，而不是直接保存解析后的 <code>dark</code> / <code>light</code>？</p><p><strong>答</strong>：保存 <code>system</code> 保留了「跟随系统」这一意图。若直接存解析结果，用户在系统里切换明暗后页面不会跟随，因为应用已经把它当成一次手动选择。正确做法是同时记录模式与解析值：模式用于 UI 与持久化，解析值用于当前渲染。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>在示例中切换浅色 / 深色 / 跟随系统，观察语义令牌与对比度读数变化：<a href="./../../examples/architecture/03-theming-dark-light">examples/architecture/03-theming-dark-light</a></li><li>把主题脚本临时移到 body 末尾，刷新页面，观察首帧闪白。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 66 话《Tailwind 与原生 CSS 的边界》——工具类与组件 CSS 不是替代关系，而是分工关系。</p>',22)])])}const g=a(i,[["render",d]]);export{u as __pageData,g as default};
